def _hr_merge_count(a):
    if len(a) <= 1:
        return a[:], 0
    mid = len(a) // 2
    left, il = _hr_merge_count(a[:mid])
    right, ir = _hr_merge_count(a[mid:])
    merged = []; inv = il + ir; i = j = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            merged.append(left[i]); i += 1
        else:
            merged.append(right[j]); j += 1; inv += len(left) - i
    merged.extend(left[i:]); merged.extend(right[j:])
    return merged, inv


