def score_code_gen(text: str) -> _BenchmarkOutcome:
    """Execute model's Python in subprocess (30s safety timeout); 13 hidden tests.

    The performance-gated inversion-count case uses SIGALRM inside the subprocess
    to fail naive O(n^2) solutions within an 8-second inner budget.
    """
    m = re.search(r"```[Pp]ython\s*\n(.*?)```", text, re.DOTALL)
    code = m.group(1).strip() if m else text.strip()

    required = {"sliding_window_median", "burst_balloons", "count_inversions"}
    if not all(name in code or name in text for name in required):
        return _BenchmarkOutcome(
            score=0.0, passed=False,
            raw_output="ERROR: missing required function definition(s)",
        )

    tmpdir = tempfile.mkdtemp(prefix="hr_livebench_")
    try:
        test_file = os.path.join(tmpdir, "test_three.py")
        with open(test_file, "w") as f:
            f.write(code)
            f.write("\n")
            f.write(_CODE_GEN_HARNESS)

        try:
            proc = run_sandboxed(Path(tmpdir), [Path(test_file).name], 30)
        except subprocess.TimeoutExpired:
            return _BenchmarkOutcome(
                score=0.0, passed=False, raw_output="ERROR: timeout",
            )
        except SandboxUnavailableError as exc:
            return _BenchmarkOutcome(
                score=0.0, passed=False, raw_output=f"ERROR: {exc}",
            )

        if proc.returncode != 0:
            snippet = (proc.stderr or "").strip()[:500]
            return _BenchmarkOutcome(
                score=0.0, passed=False,
                raw_output=f"ERROR: execution failed: {snippet}",
            )

        hr_match = re.search(r"HRTESTS=(\[.*?\])", proc.stdout)
        if not hr_match:
            return _BenchmarkOutcome(
                score=0.0, passed=False,
                raw_output=f"ERROR: no HRTESTS output; stdout={proc.stdout[:300]}",
            )
        try:
            results = json.loads(hr_match.group(1))
        except json.JSONDecodeError:
            return _BenchmarkOutcome(
                score=0.0, passed=False, raw_output="ERROR: invalid HRTESTS JSON",
            )
        if not isinstance(results, list) or len(results) != 13:
            n = len(results) if isinstance(results, list) else type(results).__name__
            return _BenchmarkOutcome(
                score=0.0, passed=False,
                raw_output=f"ERROR: expected 13 HRTESTS results, got {n}",
            )

        passed_count = sum(1 for r in results if r is True)
        score = (passed_count / 13) * 100.0
        item_scores = [(f"test.{i:02d}", bool(r)) for i, r in enumerate(results)]
        return _BenchmarkOutcome(
            score=score, passed=(score == 100.0),
            raw_output=f"{passed_count}/13 tests passed",
            item_scores=item_scores,
        )
    except Exception as e:
        return _BenchmarkOutcome(score=0.0, passed=False, raw_output=f"ERROR: {e}")
    finally:
        shutil.rmtree(tmpdir, ignore_errors=True)

__all__ = ["score_code_gen"]
